// Package pattern defines the dot-pattern generator interface used by
// the PDF pipeline to obtain an Ncode bitmap for a given page.
//
// The concrete algorithm that produces patterns compatible with the Neo
// smartpen is proprietary. This SDK ships one production-grade Generator
// in pattern/neolab that delegates to NeoLAB's own .NET assembly via a
// small C# wrapper (see tools/ncode-cli). Library consumers may also
// implement Generator themselves to plug in alternative back-ends or
// stub generators for tests.
package pattern

import (
	"context"
	"errors"

	"github.com/Post-Math/Ncode-SDK-for-Linux/ncode"
)

// Bitmap is the 1-bpp dot/line raster returned by a Generator. Pixel 0
// means "dot/ink" (a position the Neo smartpen is meant to see), pixel 1
// means "background". This matches the convention used by NeoLAB's
// reference MuPDF sample.
type Bitmap struct {
	Width, Height int    // in pixels
	DPI           int    // 600 or 1200
	Data          []byte // row-major, packed MSB-first: 8 pixels per byte
}

// PixelAt returns the 1-bit value at (x, y). 0 = dot, 1 = background.
// Out of bounds returns 1.
func (b Bitmap) PixelAt(x, y int) uint8 {
	if x < 0 || y < 0 || x >= b.Width || y >= b.Height {
		return 1
	}
	stride := (b.Width + 7) / 8
	bit := b.Data[y*stride+x/8] >> uint(7-(x%8)) & 1
	return bit
}

// SetPixel writes the 1-bit value (0 or 1) at (x, y). Out-of-bounds
// writes are silently dropped (mirrors PixelAt's out-of-bounds
// convention so a caller iterating with computed offsets cannot
// crash on edge pixels).
func (b Bitmap) SetPixel(x, y int, value uint8) {
	if x < 0 || y < 0 || x >= b.Width || y >= b.Height {
		return
	}
	stride := (b.Width + 7) / 8
	idx := y*stride + x/8
	mask := byte(1 << uint(7-(x%8)))
	if value == 0 {
		b.Data[idx] &^= mask
	} else {
		b.Data[idx] |= mask
	}
}

// NewBlankBitmap allocates a bitmap where every pixel is background (1).
func NewBlankBitmap(width, height, dpi int) Bitmap {
	stride := (width + 7) / 8
	data := make([]byte, stride*height)
	for i := range data {
		data[i] = 0xFF
	}
	return Bitmap{Width: width, Height: height, DPI: dpi, Data: data}
}

// Request describes what a Generator should produce.
type Request struct {
	Page     ncode.Page
	DPI      int
	DotMode  ncode.DotMode
	Bold     bool    // maps to the SDK's isBold flag on GetImage
	DotScale float64 // used by postscript output; 1.0 = default
}

// Validate returns a descriptive error if the request is internally
// inconsistent (e.g., line mode requested for a type that cannot render
// lines, unsupported DPI).
func (r Request) Validate() error {
	if r.Page.Type == ncode.NcodeTypeNone {
		return errors.New("Page.Type is NcodeTypeNone; the generator needs a concrete encoding")
	}
	switch r.DPI {
	case 600, 1200:
	default:
		return errors.New("unsupported DPI (SDK allows 600 or 1200)")
	}
	if r.DotMode == ncode.DotModeLine && !r.Page.Type.SupportsLineMode() {
		return errors.New("line mode requires NcodeType N3C6 or G3C6")
	}
	if r.Page.WidthInch <= 0 || r.Page.HeightInch <= 0 {
		return errors.New("page dimensions must be positive (inches)")
	}
	return nil
}

// Generator produces a 1-bpp dot raster for the given page.
type Generator interface {
	// Name is a short identifier used in logs and UI.
	Name() string

	// Generate renders a single page's Ncode bitmap. Implementations
	// MUST honour ctx cancellation — for subprocess-backed generators
	// this means propagating ctx into exec.CommandContext so a
	// caller's ctx.Done() can interrupt an in-flight CLI call.
	Generate(ctx context.Context, req Request) (Bitmap, error)
}

// ErrNotImplemented may be returned by Generator implementations that
// require external configuration not yet provided.
var ErrNotImplemented = errors.New("pattern generator not implemented")

// Package pdf turns a source PDF into an Ncoded PDF the Neo smartpen
// can read.
//
// The pixel-composition rule used here is taken verbatim from NeoLAB's
// MuPDF reference sample (cpp/sampleApp(mupdf)/main.cpp:148-176 of
// https://github.com/NeoSmartpen/Ncode-SDK2.0); deviating from it risks
// producing PDFs the pen cannot decode.
package pdf

import (
	"fmt"
	"image"
	"os"

	hhtiff "github.com/hhrutter/tiff"

	"github.com/Post-Math/Ncode-SDK-for-Linux/pattern"
)

// CompositeCMYK applies the K-removal + Ncode-overlay rule to a single
// page. The output is an image.CMYK whose bounds match src.
//
// Rule:
//   - if Ncode pixel == 0 (dot):   CMYK = (0, 0, 0, 255)   (pure K)
//   - else (background):           CMYK = (255-R, 255-G, 255-B, 0)
//
// Forcing K to zero everywhere except on dot pixels is what makes the
// pen ignore the artwork and only see the Ncode dots.
func CompositeCMYK(src image.Image, nb pattern.Bitmap) *image.CMYK {
	b := src.Bounds()
	dst := image.NewCMYK(b)

	if rgba, ok := src.(*image.RGBA); ok {
		for y := 0; y < b.Dy(); y++ {
			rowSrc := rgba.PixOffset(b.Min.X, b.Min.Y+y)
			rowDst := dst.PixOffset(b.Min.X, b.Min.Y+y)
			for x := 0; x < b.Dx(); x++ {
				if nb.PixelAt(x, y) == 0 {
					dst.Pix[rowDst+0] = 0
					dst.Pix[rowDst+1] = 0
					dst.Pix[rowDst+2] = 0
					dst.Pix[rowDst+3] = 255
				} else {
					dst.Pix[rowDst+0] = 255 - rgba.Pix[rowSrc+0]
					dst.Pix[rowDst+1] = 255 - rgba.Pix[rowSrc+1]
					dst.Pix[rowDst+2] = 255 - rgba.Pix[rowSrc+2]
					dst.Pix[rowDst+3] = 0
				}
				rowSrc += 4
				rowDst += 4
			}
		}
		return dst
	}

	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			off := dst.PixOffset(b.Min.X+x, b.Min.Y+y)
			if nb.PixelAt(x, y) == 0 {
				dst.Pix[off+0], dst.Pix[off+1], dst.Pix[off+2], dst.Pix[off+3] = 0, 0, 0, 255
				continue
			}
			r, g, bb, _ := src.At(b.Min.X+x, b.Min.Y+y).RGBA()
			dst.Pix[off+0] = 255 - uint8(r>>8)
			dst.Pix[off+1] = 255 - uint8(g>>8)
			dst.Pix[off+2] = 255 - uint8(bb>>8)
			dst.Pix[off+3] = 0
		}
	}
	return dst
}

// CompositeCMYKArtwork is CompositeCMYK without the "dot → pure K"
// branch: artwork is everywhere (255-R, 255-G, 255-B, 0). The dot
// layer is added later as a separate ImageMask painted in pure K ink.
//
// This is the artwork half of the two-layer pipeline that NeoLAB's
// own Ncoded sample PDFs use: K ink only ever comes from the mask, so
// printer colour management cannot dilute the pen-readable pixels.
func CompositeCMYKArtwork(src image.Image) *image.CMYK {
	b := src.Bounds()
	dst := image.NewCMYK(b)
	if rgba, ok := src.(*image.RGBA); ok {
		for y := 0; y < b.Dy(); y++ {
			rowSrc := rgba.PixOffset(b.Min.X, b.Min.Y+y)
			rowDst := dst.PixOffset(b.Min.X, b.Min.Y+y)
			for x := 0; x < b.Dx(); x++ {
				dst.Pix[rowDst+0] = 255 - rgba.Pix[rowSrc+0]
				dst.Pix[rowDst+1] = 255 - rgba.Pix[rowSrc+1]
				dst.Pix[rowDst+2] = 255 - rgba.Pix[rowSrc+2]
				dst.Pix[rowDst+3] = 0
				rowSrc += 4
				rowDst += 4
			}
		}
		return dst
	}
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			off := dst.PixOffset(b.Min.X+x, b.Min.Y+y)
			r, g, bb, _ := src.At(b.Min.X+x, b.Min.Y+y).RGBA()
			dst.Pix[off+0] = 255 - uint8(r>>8)
			dst.Pix[off+1] = 255 - uint8(g>>8)
			dst.Pix[off+2] = 255 - uint8(bb>>8)
			dst.Pix[off+3] = 0
		}
	}
	return dst
}

// saveCMYKTIFF writes img losslessly as a CMYK TIFF with LZW + the
// predictor tag. pdfcpu's ImportImagesFile accepts this format directly,
// and hhrutter/tiff is already a transitive dep so nothing new is
// introduced.
//
// Lossless matters for Ncode 1-pixel dots: any DCT-based codec at
// 600 DPI can smear a single black pixel into adjacent cells, and the
// pen's dot detector is threshold-based on the K channel.
func saveCMYKTIFF(path string, img *image.CMYK) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	if err := hhtiff.Encode(f, img, &hhtiff.Options{
		Compression: hhtiff.LZW,
		Predictor:   true,
	}); err != nil {
		return fmt.Errorf("encode tiff: %w", err)
	}
	return nil
}

package pdf

import (
	"fmt"

	"github.com/pdfcpu/pdfcpu/pkg/pdfcpu/model"
	"github.com/pdfcpu/pdfcpu/pkg/pdfcpu/types"

	"github.com/Post-Math/Ncode-SDK-for-Linux/pattern"
)

// pageArtifact bundles the per-page outputs of processPage. The artwork
// is flushed to disk (multi-MB CMYK) and the mask rides in memory
// (~4–5 MB packed 1-bit per A4 page at 600 DPI — cheaper than a
// round-trip through PNG).
type pageArtifact struct {
	artworkTIFF string
	mask        pattern.Bitmap
	orient      Orientation
}

// buildImageMaskXObject packs bm into a 1-bpp ImageMask stream and
// adds it to ctx as a new indirect object. The returned IndirectRef is
// the handle attached to each page's /Resources/XObject map.
//
// The bitmap convention is "0 = dot, 1 = background". With the
// /Decode [0 1] entry below, PDF paints the current fill colour where
// the stored bit is 0 — i.e., on dot pixels — and leaves the rest
// transparent. bm.Data is already stride-aligned to (width+7)/8 bytes,
// MSB-first, which is exactly the row layout PDF expects for 1-bpp.
func buildImageMaskXObject(ctx *model.Context, bm pattern.Bitmap) (*types.IndirectRef, error) {
	sd, err := ctx.XRefTable.NewStreamDictForBuf(bm.Data)
	if err != nil {
		return nil, fmt.Errorf("new stream: %w", err)
	}
	sd.InsertName("Type", "XObject")
	sd.InsertName("Subtype", "Image")
	sd.InsertInt("Width", bm.Width)
	sd.InsertInt("Height", bm.Height)
	sd.InsertInt("BitsPerComponent", 1)
	sd.InsertBool("ImageMask", true)
	sd.Insert("Decode", types.Array{types.Float(0), types.Float(1)})
	if err := sd.Encode(); err != nil {
		return nil, fmt.Errorf("encode mask: %w", err)
	}
	return ctx.XRefTable.IndRefForNewObject(*sd)
}

// appendContentStream adds a new content stream to pageDict that draws
// maskRef as a 1×1-scaled ImageMask filling the page. The caller must
// have already inserted maskRef into Resources/XObject under maskName.
//
// PDF's /Contents can be either a single indirect reference to one
// stream or an array of indirect references to several streams that
// the reader concatenates in order. We always produce the array form
// because ImportImagesFile leaves a single-ref /Contents behind and
// we need to extend it without rewriting the existing artwork stream.
func appendContentStream(ctx *model.Context, pageDict types.Dict, maskName string, pageWpt, pageHpt float64) error {
	instr := fmt.Sprintf("q\n0 0 0 1 k\n%.4f 0 0 %.4f 0 0 cm\n/%s Do\nQ\n",
		pageWpt, pageHpt, maskName)
	sd, err := ctx.XRefTable.NewStreamDictForBuf([]byte(instr))
	if err != nil {
		return fmt.Errorf("new content stream: %w", err)
	}
	if err := sd.Encode(); err != nil {
		return fmt.Errorf("encode content: %w", err)
	}
	csRef, err := ctx.XRefTable.IndRefForNewObject(*sd)
	if err != nil {
		return fmt.Errorf("create content stream: %w", err)
	}

	existing, ok := pageDict.Find("Contents")
	if !ok {
		pageDict.Insert("Contents", types.Array{*csRef})
		return nil
	}
	switch v := existing.(type) {
	case types.Array:
		pageDict.Update("Contents", append(v, *csRef))
	case types.IndirectRef:
		pageDict.Update("Contents", types.Array{v, *csRef})
	default:
		return fmt.Errorf("unexpected /Contents type %T", existing)
	}
	return nil
}

// addMaskToResources registers maskRef under maskName in the page's
// Resources/XObject dict. If the dict already has an entry with that
// name, returns an error rather than silently overwriting.
func addMaskToResources(ctx *model.Context, pageDict types.Dict, maskRef *types.IndirectRef, maskName string) error {
	resRaw, ok := pageDict.Find("Resources")
	if !ok {
		return fmt.Errorf("page dict missing /Resources")
	}
	resDict, err := ctx.XRefTable.DereferenceDict(resRaw)
	if err != nil {
		return fmt.Errorf("deref resources: %w", err)
	}
	xoRaw, ok := resDict.Find("XObject")
	if !ok {
		xoDict := types.NewDict()
		xoDict.Insert(maskName, *maskRef)
		resDict.Insert("XObject", xoDict)
		return nil
	}
	xoDict, err := ctx.XRefTable.DereferenceDict(xoRaw)
	if err != nil {
		return fmt.Errorf("deref xobject: %w", err)
	}
	if _, exists := xoDict.Find(maskName); exists {
		return fmt.Errorf("page already has /%s xobject — refusing to overwrite", maskName)
	}
	xoDict.Insert(maskName, *maskRef)
	return nil
}

#include <iostream>
#include "main.h"


/*
* Ncoded PDF sample code using mupdf library
* This code can be updated from user's request.
* This project is tested under win32 environment.
*/



static fz_context *ctx = NULL;			// global mupdf context
static pdf_document *doc_dest = NULL;	// for Ncoded pdf



static void add_image_res(pdf_obj *resources, char *name, fz_image *image)
{
	pdf_obj *subres, *ref;

	subres = pdf_dict_get(ctx, resources, PDF_NAME_XObject);
	if (!subres)
	{
		subres = pdf_new_dict(ctx, doc_dest, 10);
		pdf_dict_put_drop(ctx, resources, PDF_NAME_XObject, subres);
	}

	ref = pdf_add_image(ctx, doc_dest, image, 0);
	pdf_dict_puts(ctx, subres, name, ref);
	pdf_drop_obj(ctx, ref);

	fz_drop_image(ctx, image);
}


static void make_contents(fz_buffer* contents, char *name, int w, int h)
{
	char line[4096];

	fz_append_string(ctx, contents, "q");
	fz_append_byte(ctx, contents, '\n');

	sprintf(line, "%d 0 0 %d 0 0 cm", w, h);
	fz_append_string(ctx, contents, line);
	fz_append_byte(ctx, contents, '\n');

	sprintf(line, "/%s Do", name);
	fz_append_string(ctx, contents, line);
	fz_append_byte(ctx, contents, '\n');

	fz_append_string(ctx, contents, "Q");
	fz_append_byte(ctx, contents, '\n');
}


static void create_page(char *name, int w, int h, fz_image *image)
{
	int rotate = 0;


	fz_rect mediabox = { 0, 0, w, h };
	pdf_obj *resources;
	pdf_obj *page;
	fz_buffer *contents;

	// make resource
	resources = pdf_new_dict(ctx, doc_dest, 2);
	add_image_res(resources, name, image);


	// make contents
	contents = fz_new_buffer(ctx, 1024);
	make_contents(contents, name, w, h);


	// make and insert page
	page = pdf_add_page(ctx, doc_dest, &mediabox, rotate, resources, contents);
	pdf_insert_page(ctx, doc_dest, -1, page);


	// release
	pdf_drop_obj(ctx, page);
	fz_drop_buffer(ctx, contents);
	pdf_drop_obj(ctx, resources);
}


void main()
{
	printf("1) Initializing context, handler, pdf document\n\n");
	pdf_write_options opts = { 0 };

	ctx = fz_new_context(NULL, NULL, FZ_STORE_UNLIMITED);

	if (!ctx)
	{
		printf("Cannot initialize context\n\n");
		exit(1);
	}
	pdf_parse_write_options(ctx, &opts, "compress");
	fz_register_document_handlers(ctx);				// get handle
	doc_dest = pdf_create_document(ctx);			// open destination document


	printf("2) Loading source pdf file\n\n");
	fz_document* doc_src;
	doc_src = fz_open_document(ctx, "input.pdf");	// open source document


	printf("3) Making Ncoded pages\n\n");
	int i;
	int pageCount = doc_src->count_pages(ctx, doc_src);
	int dpi = 600;

	for (i = 0; i < pageCount; ++i)
	{
		printf("   3-1(page %d)) Loading source page and Ncode image\n", i);
		fz_page *page;
		fz_rect rect;
		fz_matrix ctm = fz_identity;

		page = fz_load_page(ctx, doc_src, i);		// load page
		fz_bound_page(ctx, page, &rect);			// get size of page

		// calculate scale and set matrix
		float scale = dpi / 72.0f;
		int w = (int)(rect.x1 * scale);
		int h = (int)(rect.y1 * scale);
		fz_scale(&ctm, scale, scale);

		// make Ncoded pixmap
		// pixSrc : background from pdf
		// pixNcode : Ncode image
		// pixRemovedK : destination image = pixSrc(remove K) + pixNcode
		fz_pixmap *pixSrc;
		fz_pixmap *pixRemovedK;

		pixSrc = fz_new_pixmap_from_page_contents(ctx, page, &ctm, fz_device_rgb(ctx), 0);	// RGB
		pixRemovedK = fz_new_pixmap(ctx, fz_device_cmyk(ctx), pixSrc->w, pixSrc->h, 0);		// CMYK

		char name_Ncoded_image[100];	// filename
		sprintf(name_Ncoded_image, "Ncode_%d.png", i);
		fz_image *imageNcodeSrc = fz_new_image_from_file(ctx, name_Ncoded_image);
		fz_pixmap *pixNcode = imageNcodeSrc->get_pixmap(ctx, imageNcodeSrc, NULL, pixSrc->w, pixSrc->h, NULL);


		printf("   3-2(page %d)) Combining background image(removed K) and Ncode image\n", i);
		int x, y;
		for (y = 0; y < pixSrc->h; ++y)
		{
			for (x = 0; x < pixSrc->w; ++x)
			{
				// p_dest = p_src + p_Ncode
				unsigned char *p_src = &pixSrc->samples[(y * pixSrc->w + x) * pixSrc->n];
				unsigned char *p_Ncode = &pixNcode->samples[(y * pixNcode->w + x) * pixNcode->n];
				unsigned char *p_dest = &pixRemovedK->samples[(y * pixSrc->w + x) * pixRemovedK->n];

				// draw Ncode dot
				if (p_Ncode[0] == 0)
				{
					p_dest[0] = 0;
					p_dest[1] = 0;
					p_dest[2] = 0;
					p_dest[3] = 255;
				}
				// draw background with removed K
				else
				{
					p_dest[0] = 255 - p_src[0];		// C
					p_dest[1] = 255 - p_src[1];		// M
					p_dest[2] = 255 - p_src[2];		// Y
					p_dest[3] = 0;					// K = 0
				}
			}
		}

		// final Ncoded pixmap -> image
		fz_image *imageNcoded = fz_new_image_from_pixmap(ctx, pixRemovedK, NULL);


		printf("   3-3(page %d)) Inserting Ncoded image to destination pdf file\n", i);
		char id[100];
		sprintf(id, "I%d", i);
		create_page(id, (int)rect.x1, (int)rect.y1, imageNcoded);

		// release objects
		fz_drop_page(ctx, page);
		fz_drop_pixmap(ctx, pixSrc);
		fz_drop_pixmap(ctx, pixRemovedK);
		fz_drop_pixmap(ctx, pixNcode);
		fz_drop_image(ctx, imageNcodeSrc);
		fz_drop_image(ctx, imageNcoded);

		printf("\n");
	}


	printf("4) Saving Ncoded pdf file\n\n");
	pdf_save_document(ctx, doc_dest, "Ncoded.pdf", &opts);


	// release objects
	pdf_drop_document(ctx, doc_dest);
	fz_drop_document(ctx, doc_src);
	fz_flush_warnings(ctx);
	fz_drop_context(ctx);


	printf("complete");
	getchar();
}

// Package neolab implements pattern.Generator on top of NeoLAB's
// official .NET dot-pattern algorithm.
//
// NeoLAB ships the algorithm only as a managed Windows DLL
// (NeoLABNcodeSDK.dll), so this package shells out to a small C#
// console wrapper (tools/ncode-cli) once per page. The wrapper runs
// directly on Windows; on Linux/macOS this package prefixes it with
// "mono" — see docs/linux-support.md and tools/ncode-cli/MONO_PATH_WORKAROUND.md
// for the path-handling quirk that has to be patched for the SDK to
// run under Mono at all.
//
// Until an appSecretKey is provisioned, Generate returns a descriptive
// error so callers can route the user to a settings screen.
package neolab

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"image/png"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"

	"github.com/Post-Math/Ncode-SDK-for-Linux/ncode"
	"github.com/Post-Math/Ncode-SDK-for-Linux/pattern"
)

// Generator drives ncode-cli.exe to produce a single-page Ncode PNG and
// converts it into pattern.Bitmap. Zero-value fields make Generate fail
// with a clear message so a frontend can prompt for configuration.
type Generator struct {
	// ExePath is the absolute path to ncode-cli.exe. Required.
	ExePath string

	// AppKey is the NeoLAB-issued appSecretKey. Required; the CLI
	// passes it to CNcodeSDK.Init and then GetTickets(), both of
	// which validate against the REST endpoint.
	AppKey string

	// TicketIdx selects which entry of GetTickets() to use. 0 picks
	// the first available ticket; surface this in the UI for users
	// with multiple provisioned ranges.
	TicketIdx int

	// MonoPath overrides the "mono" binary used on non-Windows hosts.
	// Empty means look up "mono" on PATH.
	MonoPath string
}

// Name identifies this generator for logs and UI badges.
func (Generator) Name() string { return "neolab" }

// cliResponse mirrors the JSON ncode-cli prints to stdout on success.
type cliResponse struct {
	PageID     string  `json:"pageId"`
	PngPath    string  `json:"pngPath"`
	WidthInch  float64 `json:"widthInch"`
	HeightInch float64 `json:"heightInch"`
	DPI        int     `json:"dpi"`
}

// Generate runs ncode-cli once per page. The CLI writes the PNG to a
// path we pass in; we then decode it into a 1-bpp Bitmap (dot=0). The
// passed ctx is propagated into exec.CommandContext so a caller can
// cancel a stuck CLI subprocess.
func (g Generator) Generate(ctx context.Context, req pattern.Request) (pattern.Bitmap, error) {
	if err := req.Validate(); err != nil {
		return pattern.Bitmap{}, err
	}
	if g.ExePath == "" {
		return pattern.Bitmap{}, errors.New("neolab: ExePath is empty — set it before calling Generate")
	}
	if g.AppKey == "" {
		return pattern.Bitmap{}, errors.New("neolab: AppKey is empty — provision one from NeoLAB")
	}
	if _, err := os.Stat(g.ExePath); err != nil {
		return pattern.Bitmap{}, fmt.Errorf("neolab: ncode-cli not found at %s: %w", g.ExePath, err)
	}

	tmpDir, err := os.MkdirTemp("", "ncode-cli-*")
	if err != nil {
		return pattern.Bitmap{}, fmt.Errorf("neolab: temp dir: %w", err)
	}
	defer os.RemoveAll(tmpDir)
	outPNG := filepath.Join(tmpDir, "page.png")

	args := buildArgs(g, req, outPNG)

	cmd := cmdBuilder(ctx, g, args)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		return pattern.Bitmap{}, fmt.Errorf("neolab: ncode-cli failed: %w\nstderr: %s", err, stderr.String())
	}

	var resp cliResponse
	if err := json.Unmarshal(bytes.TrimSpace(out), &resp); err != nil {
		return pattern.Bitmap{}, fmt.Errorf("neolab: parse cli json: %w\nstdout: %s", err, string(out))
	}

	bm, err := loadPNGAsBitmap(resp.PngPath, req.DPI)
	if err != nil {
		return pattern.Bitmap{}, fmt.Errorf("neolab: decode png: %w", err)
	}
	return bm, nil
}

// buildArgs constructs the ncode-cli `generate` argument vector. Pure
// function — no I/O — so tests can inspect the args directly without
// invoking a subprocess.
func buildArgs(g Generator, req pattern.Request, outPNG string) []string {
	args := []string{
		"generate",
		"--app-key", g.AppKey,
		"--ticket-idx", fmt.Sprintf("%d", g.TicketIdx),
		"--type", req.Page.Type.String(),
		"--section", fmt.Sprintf("%d", req.Page.ID.Section),
		"--owner", fmt.Sprintf("%d", req.Page.ID.Owner),
		"--book", fmt.Sprintf("%d", req.Page.ID.Book),
		"--page", fmt.Sprintf("%d", req.Page.ID.Page),
		"--width-inch", fmt.Sprintf("%.6f", req.Page.WidthInch),
		"--height-inch", fmt.Sprintf("%.6f", req.Page.HeightInch),
		"--dpi", fmt.Sprintf("%d", req.DPI),
		"--out-png", outPNG,
	}
	if req.Bold {
		args = append(args, "--bold")
	}
	if req.DotMode == ncode.DotModeLine {
		args = append(args, "--line-mode")
	}
	return args
}

// cmdBuilder composes the exec.Cmd that invokes ncode-cli. On Windows
// the .exe runs natively; on Linux/macOS it runs under Mono. Override
// MonoPath to point at a non-default mono runtime.
//
// Exposed as a package-level var so tests can swap in a fake builder
// that returns a synthetic command (e.g., one that prints canned JSON
// to stdout). The default value behaves identically to a method.
var cmdBuilder = func(ctx context.Context, g Generator, args []string) *exec.Cmd {
	if runtime.GOOS == "windows" {
		return exec.CommandContext(ctx, g.ExePath, args...)
	}
	mono := g.MonoPath
	if mono == "" {
		mono = "mono"
	}
	full := append([]string{g.ExePath}, args...)
	return exec.CommandContext(ctx, mono, full...)
}

// loadPNGAsBitmap reads a PNG produced by CNcodeSDK.GetImage and encodes
// it as a 1-bpp pattern.Bitmap following the "0 = dot" convention. The
// SDK writes black dots on white; any pixel darker than mid-grey is
// treated as a dot.
func loadPNGAsBitmap(path string, dpi int) (pattern.Bitmap, error) {
	f, err := os.Open(path)
	if err != nil {
		return pattern.Bitmap{}, err
	}
	defer f.Close()
	img, err := png.Decode(f)
	if err != nil {
		return pattern.Bitmap{}, err
	}
	b := img.Bounds()
	bm := pattern.NewBlankBitmap(b.Dx(), b.Dy(), dpi)
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			r, g, bl, _ := img.At(b.Min.X+x, b.Min.Y+y).RGBA()
			avg := (int(r>>8) + int(g>>8) + int(bl>>8)) / 3
			if avg < 128 {
				bm.SetPixel(x, y, 0)
			}
		}
	}
	return bm, nil
}

package pdf

import (
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/gen2brain/go-fitz"
	"github.com/pdfcpu/pdfcpu/pkg/api"
	pdfcpu "github.com/pdfcpu/pdfcpu/pkg/pdfcpu"
	"github.com/pdfcpu/pdfcpu/pkg/pdfcpu/model"
	"github.com/pdfcpu/pdfcpu/pkg/pdfcpu/types"

	"github.com/Post-Math/Ncode-SDK-for-Linux/ncode"
	"github.com/Post-Math/Ncode-SDK-for-Linux/pattern"
	"github.com/Post-Math/Ncode-SDK-for-Linux/pattern/kernels"
)

// PublishRequest is the end-to-end input to Publish.
type PublishRequest struct {
	Input     string            // source PDF path
	Output    string            // destination PDF path
	Generator pattern.Generator // Ncode bitmap generator
	Ticket    ncode.Ticket      // allocation to draw page IDs from
	DPI       int               // 600 or 1200
	DotMode   ncode.DotMode
	Bold      bool

	// OwnerStart / BookStart / PageStart pick where to start within
	// the ticket's allotment. For a one-PDF-per-owner workflow the
	// caller typically issues a fresh ticket per PDF and leaves the
	// offsets at zero.
	OwnerStart int
	BookStart  int
	PageStart  int

	// ClusterMerge collapses every zero-pixel cluster in the SDK
	// bitmap to its single top-left pixel before the raster mask is
	// built. With Bold=true the SDK emits 2×2 clusters; this flag
	// reduces them to 1×1 so a subsequent dilation kernel sees the
	// same shape a Bold=false issue would have produced.
	ClusterMerge bool

	// DilationKernel, when non-empty, expands every zero pixel of the
	// SDK bitmap by this kernel before the ImageMask is built.
	// Use kernels.Tri3Up / Tri3Down / Tri4Up / Tri4Down / Diamond4
	// or supply your own offsets. See pattern/kernels.
	DilationKernel kernels.Kernel

	// DilationKernelB, when non-empty, alternates with DilationKernel
	// in row-major discovery order. Used by the triangle-up/down
	// sweep to print ▲▽▲▽ patterns so any halftone interaction with
	// a single orientation averages across both shapes.
	DilationKernelB kernels.Kernel

	// DilationSquareN, when > 1, expands every zero pixel to an N×N
	// filled square. Ignored when DilationKernel is set.
	DilationSquareN int

	// DilationDiscR, when > 0, expands every zero pixel to a filled
	// disc of the given radius (pixels). Ignored when DilationKernel
	// is set.
	DilationDiscR float64
}

// ProgressEvent is emitted as each page completes.
type ProgressEvent struct {
	PageIndex int // 0-based
	PageCount int
	PageID    ncode.PageID
	Err       error // non-nil if this page failed
}

// Publish runs the full pipeline and returns the number of pages that
// were written to the output PDF. Returns 0 together with a non-nil
// error on any failure — the caller must not advance any cursor in
// that case. Progress callbacks run on the caller's goroutine; cb may
// be nil.
func Publish(ctx context.Context, req PublishRequest, cb func(ProgressEvent)) (int, error) {
	if req.DPI == 0 {
		req.DPI = 600
	}
	if req.DPI != 600 && req.DPI != 1200 {
		return 0, fmt.Errorf("DPI=%d not supported (SDK allows 600 or 1200)", req.DPI)
	}
	if req.Generator == nil {
		return 0, fmt.Errorf("Generator is required")
	}
	if req.OwnerStart < 0 || req.OwnerStart >= req.Ticket.OwnerSize {
		return 0, fmt.Errorf("OwnerStart=%d out of range [0, %d)", req.OwnerStart, req.Ticket.OwnerSize)
	}
	if req.BookStart < 0 || req.BookStart >= req.Ticket.BookSize {
		return 0, fmt.Errorf("BookStart=%d out of range [0, %d)", req.BookStart, req.Ticket.BookSize)
	}
	if req.PageStart < 0 {
		return 0, fmt.Errorf("PageStart=%d must be non-negative", req.PageStart)
	}
	doc, err := fitz.New(req.Input)
	if err != nil {
		return 0, fmt.Errorf("open source PDF: %w", err)
	}
	defer doc.Close()

	pageCount := doc.NumPage()
	if pageCount == 0 {
		return 0, fmt.Errorf("source PDF has no pages")
	}
	if req.PageStart+pageCount > req.Ticket.PageSize {
		return 0, fmt.Errorf("ticket page range too small: need %d pages from offset %d, size=%d",
			pageCount, req.PageStart, req.Ticket.PageSize)
	}

	tmpDir, err := os.MkdirTemp("", "ncode-pdf-*")
	if err != nil {
		return 0, fmt.Errorf("temp dir: %w", err)
	}
	defer os.RemoveAll(tmpDir)

	artifacts := make([]*pageArtifact, 0, pageCount)
	for i := range pageCount {
		if err := ctx.Err(); err != nil {
			return 0, err
		}

		pageID, err := req.Ticket.Resolve(req.OwnerStart, req.BookStart, req.PageStart+i)
		if err != nil {
			return 0, fmt.Errorf("resolve page %d: %w", i, err)
		}

		art, err := processPage(ctx, doc, i, pageID, req, tmpDir)
		if cb != nil {
			cb(ProgressEvent{PageIndex: i, PageCount: pageCount, PageID: pageID, Err: err})
		}
		if err != nil {
			return 0, fmt.Errorf("page %d: %w", i, err)
		}
		artifacts = append(artifacts, art)
	}

	if err := assemblePDF(artifacts, req.Output); err != nil {
		return 0, fmt.Errorf("assemble PDF: %w", err)
	}
	return pageCount, nil
}

// processPage normalises one source page to A4 and emits a page
// artefact: a CMYK-only artwork TIFF (no dots baked in) on disk, plus
// the raw Ncode bitmap carried in memory for later conversion into a
// 1-bpp ImageMask.
func processPage(ctx context.Context, doc *fitz.Document, idx int, id ncode.PageID, req PublishRequest, outDir string) (*pageArtifact, error) {
	bounds, err := doc.Bound(idx)
	if err != nil {
		return nil, fmt.Errorf("bound: %w", err)
	}

	orient := detectOrientation(float64(bounds.Dx()), float64(bounds.Dy()))
	a4W, a4H := a4Inches(orient)

	srcRaster, err := doc.ImageDPI(idx, float64(req.DPI))
	if err != nil {
		return nil, fmt.Errorf("render: %w", err)
	}
	canvas := fitIntoA4(srcRaster, orient, req.DPI)

	bm, err := req.Generator.Generate(ctx, pattern.Request{
		Page: ncode.Page{
			Type:       req.Ticket.Type,
			ID:         id,
			WidthInch:  a4W,
			HeightInch: a4H,
		},
		DPI:     req.DPI,
		DotMode: req.DotMode,
		Bold:    req.Bold,
	})
	if err != nil {
		return nil, fmt.Errorf("generate ncode: %w", err)
	}

	if req.ClusterMerge {
		if !req.Bold {
			return nil, fmt.Errorf("ClusterMerge requires Bold=true (nobold bitmap is already 1px/dot)")
		}
		if req.DotMode != ncode.DotModeDot {
			return nil, fmt.Errorf("ClusterMerge requires DotMode=dot (line strokes are not separable clusters)")
		}
		bm = kernels.ReduceClusterTopLefts(bm)
	}

	hasDilation := req.DilationSquareN > 1 || req.DilationDiscR > 0 || len(req.DilationKernel) > 0
	if hasDilation && req.Bold && !req.ClusterMerge {
		return nil, fmt.Errorf("Dilation expects Bold=false input (1px/dot); SDK already dilates Bold=true to 2×2")
	}
	switch {
	case len(req.DilationKernel) > 0 && len(req.DilationKernelB) > 0:
		bm = kernels.ApplyAlternating(bm, req.DilationKernel, req.DilationKernelB)
	case len(req.DilationKernel) > 0:
		bm = kernels.ApplyKernel(bm, req.DilationKernel)
	case req.DilationSquareN > 1:
		bm = kernels.ApplySquare(bm, req.DilationSquareN)
	case req.DilationDiscR > 0:
		bm = kernels.ApplyDisc(bm, req.DilationDiscR)
	}

	artwork := CompositeCMYKArtwork(canvas)
	artworkTIFF := filepath.Join(outDir, fmt.Sprintf("artwork-%05d.tif", idx+1))
	if err := saveCMYKTIFF(artworkTIFF, artwork); err != nil {
		return nil, fmt.Errorf("save artwork tiff: %w", err)
	}
	return &pageArtifact{artworkTIFF: artworkTIFF, mask: bm, orient: orient}, nil
}

// assemblePDF builds a two-layer PDF matching NeoLAB's own Ncoded
// sample structure: a DeviceCMYK artwork image carries the source
// page content, and a 1-bpp ImageMask drawn in pure K ink on top
// carries the Ncode dots.
func assemblePDF(artifacts []*pageArtifact, outputPath string) error {
	if len(artifacts) == 0 {
		return fmt.Errorf("no pages to assemble")
	}
	tmpDir, err := os.MkdirTemp("", "ncode-assemble-*")
	if err != nil {
		return fmt.Errorf("assemble tmp dir: %w", err)
	}
	defer os.RemoveAll(tmpDir)

	conf := model.NewDefaultConfiguration()
	singlePDFs := make([]string, 0, len(artifacts))
	for i, art := range artifacts {
		imp := pdfcpu.DefaultImportConfig()
		// Pin the MediaBox in both orientations so appendContentStream's
		// pageWpt/pageHpt cm matrix matches what pdfcpu actually writes —
		// otherwise the portrait branch can fall through to whatever
		// DefaultImportConfig defaults to in a future pdfcpu release.
		pw, ph := a4Points(art.orient)
		imp.PageDim = &types.Dim{Width: pw, Height: ph}
		if art.orient == OrientLandscape {
			imp.PageSize = "A4L"
		} else {
			imp.PageSize = "A4"
		}
		imp.Pos = types.Center
		imp.Scale = 1.0
		imp.ScaleAbs = false

		single := filepath.Join(tmpDir, fmt.Sprintf("p-%05d.pdf", i))
		if err := api.ImportImagesFile([]string{art.artworkTIFF}, single, imp, conf); err != nil {
			return fmt.Errorf("import artwork page %d: %w", i, err)
		}
		singlePDFs = append(singlePDFs, single)
	}

	if len(singlePDFs) == 1 {
		if err := moveFile(singlePDFs[0], outputPath); err != nil {
			return fmt.Errorf("move single page: %w", err)
		}
	} else if err := api.MergeCreateFile(singlePDFs, outputPath, false, conf); err != nil {
		return fmt.Errorf("merge: %w", err)
	}

	return injectNcodeMasks(outputPath, artifacts)
}

// injectNcodeMasks opens the artwork-only PDF, adds a 1-bpp ImageMask
// XObject + a pure-K draw instruction to each page, and atomically
// rewrites the file. We write to a sibling temp path and rename on
// success so a mid-write failure cannot leave the artwork-only PDF
// in a half-rewritten state.
func injectNcodeMasks(pdfPath string, artifacts []*pageArtifact) error {
	pdfCtx, err := api.ReadContextFile(pdfPath)
	if err != nil {
		return fmt.Errorf("reopen for mask inject: %w", err)
	}
	if pdfCtx.XRefTable.PageCount != len(artifacts) {
		return fmt.Errorf("page count mismatch: pdf=%d artifacts=%d",
			pdfCtx.XRefTable.PageCount, len(artifacts))
	}

	for i, art := range artifacts {
		pageNr := i + 1
		pd, _, _, err := pdfCtx.XRefTable.PageDict(pageNr, false)
		if err != nil {
			return fmt.Errorf("page %d dict: %w", pageNr, err)
		}

		maskRef, err := buildImageMaskXObject(pdfCtx, art.mask)
		if err != nil {
			return fmt.Errorf("page %d mask xobject: %w", pageNr, err)
		}

		const maskName = "NcMask"
		if err := addMaskToResources(pdfCtx, pd, maskRef, maskName); err != nil {
			return fmt.Errorf("page %d resources: %w", pageNr, err)
		}

		pw, ph := a4Points(art.orient)
		if err := appendContentStream(pdfCtx, pd, maskName, pw, ph); err != nil {
			return fmt.Errorf("page %d content stream: %w", pageNr, err)
		}
	}

	tmpPath := pdfPath + ".inject.tmp"
	if err := api.WriteContextFile(pdfCtx, tmpPath); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("write merged pdf: %w", err)
	}
	if err := os.Rename(tmpPath, pdfPath); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("rename injected pdf: %w", err)
	}
	return nil
}

// moveFile relocates src to dst, falling back to copy+remove when
// os.Rename fails with EXDEV (cross-device link).
func moveFile(src, dst string) error {
	if err := os.Rename(src, dst); err == nil {
		return nil
	}
	in, err := os.Open(src)
	if err != nil {
		return fmt.Errorf("open src: %w", err)
	}
	defer in.Close()
	out, err := os.Create(dst)
	if err != nil {
		return fmt.Errorf("create dst: %w", err)
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		_ = os.Remove(dst)
		return fmt.Errorf("copy: %w", err)
	}
	if err := out.Close(); err != nil {
		_ = os.Remove(dst)
		return fmt.Errorf("close dst: %w", err)
	}
	_ = os.Remove(src)
	return nil
}

// publish is the production end-to-end example for the Postmath
// Ncode SDK. It opens an input PDF, generates Ncode bitmaps via the
// NeoLAB subprocess generator, applies the production-default 3-pixel
// triangle alternating dilation kernel, and writes a pen-readable
// two-layer Ncoded PDF to disk.
//
// This example **requires** NeoLAB-issued assets (see runtime
// requirements in the repository README). It does not fall back to
// any offline stub — if any required env var is missing the example
// fails fast with a clear message. For offline / CI smoke tests run
// the SDK's own test suite instead: `go test ./...` exercises the
// PDF pipeline end-to-end without NeoLAB credentials, using the
// internal stub Generator in `pattern/stub`.
//
// # Required env vars
//
//	NCODE_APPKEY        NeoLAB-issued application key
//	NCODE_CLI_EXE       path to ncode-cli.exe (run under Mono on Linux/macOS)
//	NCODE_INPUT_PDF     source PDF path
//	NCODE_OUTPUT_PDF    destination PDF path
//	NCODE_SECTION       int — first axis of the NeoLAB-granted range
//	NCODE_OWNER         absolute owner index for this print run
//	NCODE_BOOK          absolute book index
//	NCODE_PAGE_START    first page index
//	NCODE_PAGE_SIZE     ticket page-axis size; must be ≥ PDF page count
//
// # Optional env vars
//
//	NCODE_TYPE          N3C6 / G3C6 / S1C6 / P1C6 (default: N3C6)
//	NCODE_TICKET_IDX    GetTickets() index when the app key has multiple
//	                    provisioned ranges (default: 0)
//	NCODE_MONO_PATH     mono executable path on Linux/macOS (default: "mono"
//	                    looked up via PATH; ignored on Windows)
//
// To discover what (section, owner, book, page) ranges your app key
// is provisioned for, run the companion `discover-tickets` example
// first.
package main

import (
	"context"
	"fmt"
	"os"
	"strconv"

	"github.com/Post-Math/Ncode-SDK-for-Linux/ncode"
	"github.com/Post-Math/Ncode-SDK-for-Linux/pattern/kernels"
	"github.com/Post-Math/Ncode-SDK-for-Linux/pattern/neolab"
	"github.com/Post-Math/Ncode-SDK-for-Linux/pdf"
)

func main() {
	cliExe := mustEnv("NCODE_CLI_EXE")
	appKey := mustEnv("NCODE_APPKEY")
	input := mustEnv("NCODE_INPUT_PDF")
	output := mustEnv("NCODE_OUTPUT_PDF")

	typeName := envOr("NCODE_TYPE", "N3C6")
	ncodeType, err := ncode.ParseNcodeType(typeName)
	if err != nil {
		fatal("NCODE_TYPE: %v", err)
	}

	section := mustEnvInt("NCODE_SECTION")
	owner := mustEnvInt("NCODE_OWNER")
	book := mustEnvInt("NCODE_BOOK")
	pageStart := mustEnvInt("NCODE_PAGE_START")
	pageSize := mustEnvInt("NCODE_PAGE_SIZE")

	gen := neolab.Generator{
		ExePath:   cliExe,
		AppKey:    appKey,
		TicketIdx: envOrInt("NCODE_TICKET_IDX", 0),
		MonoPath:  os.Getenv("NCODE_MONO_PATH"),
	}

	ticket := ncode.Ticket{
		ID:         "publish",
		Type:       ncodeType,
		Section:    section,
		OwnerStart: owner, OwnerSize: 1,
		BookStart: book, BookSize: 1,
		PageStart: pageStart, PageSize: pageSize,
	}

	req := pdf.PublishRequest{
		Input:           input,
		Output:          output,
		Generator:       gen,
		Ticket:          ticket,
		DPI:             600,
		DotMode:         ncode.DotModeLine,
		Bold:            false,
		DilationKernel:  kernels.Tri3Up,
		DilationKernelB: kernels.Tri3Down,
	}
	// Line mode is N3C6/G3C6 only. Other types fall back to dot mode
	// at the SDK layer; reflect that here so the example "just works"
	// regardless of the type the caller selected.
	if !ncodeType.SupportsLineMode() {
		req.DotMode = ncode.DotModeDot
	}

	pages, err := pdf.Publish(context.Background(), req, func(e pdf.ProgressEvent) {
		fmt.Printf("[%d/%d] page %s\n", e.PageIndex+1, e.PageCount, e.PageID)
	})
	if err != nil {
		fatal("publish: %v", err)
	}
	fmt.Printf("done: %d pages → %s\n", pages, output)
}

func envOr(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

func envOrInt(k string, def int) int {
	v := os.Getenv(k)
	if v == "" {
		return def
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		fatal("env %s: %v", k, err)
	}
	return n
}

func mustEnv(k string) string {
	v := os.Getenv(k)
	if v == "" {
		fatal("env %s is required", k)
	}
	return v
}

func mustEnvInt(k string) int {
	v := mustEnv(k)
	n, err := strconv.Atoi(v)
	if err != nil {
		fatal("env %s: %v", k, err)
	}
	return n
}

func fatal(fmtStr string, args ...any) {
	fmt.Fprintf(os.Stderr, "publish: "+fmtStr+"\n", args...)
	os.Exit(1)
}

